package com.primehr.learningdevelopment.plan.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="ld_idp_route",uniqueConstraints=@UniqueConstraint(name="uk_ld_idp_route_revision",columnNames={"agency_id","plan_id","route_revision"}))
public class LdIdpRoute extends RspAuditedEntity{
 public enum Status{ACTIVE,RETURNED,COMPLETED,CANCELLED,SUPERSEDED}
 @Column(name="plan_id",nullable=false,length=36)private String planId;@Column(name="route_revision",nullable=false)private int routeRevision;@Column(name="request_code",nullable=false,length=100)private String requestCode;@Column(name="business_unit_id",nullable=false)private Long businessUnitId;@Column(name="route_fingerprint",nullable=false,length=64)private String routeFingerprint;@Column(name="submitted_content_revision",nullable=false)private int submittedContentRevision;@Column(name="current_level",nullable=false)private int currentLevel;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="submitted_by",nullable=false,length=100)private String submittedBy;@Column(name="submitted_at",nullable=false)private Instant submittedAt;
 protected LdIdpRoute(){}public LdIdpRoute(String agency,String plan,int revision,String code,Long unit,String fingerprint,int contentRevision,String actor,Instant at){super(agency);planId=requiredText(plan,"planId");if(revision<1)throw new IllegalArgumentException("routeRevision must be positive");routeRevision=revision;requestCode=requiredText(code,"requestCode");businessUnitId=unit;routeFingerprint=requiredText(fingerprint,"routeFingerprint");submittedContentRevision=contentRevision;currentLevel=1;status=Status.ACTIVE;submittedBy=requiredText(actor,"actor");submittedAt=at;}public void advance(int value){currentLevel=value;}public void finish(Status value){status=value;}public String getPlanId(){return planId;}public int getRouteRevision(){return routeRevision;}public String getRequestCode(){return requestCode;}public Long getBusinessUnitId(){return businessUnitId;}public String getRouteFingerprint(){return routeFingerprint;}public int getSubmittedContentRevision(){return submittedContentRevision;}public int getCurrentLevel(){return currentLevel;}public Status getStatus(){return status;}public String getSubmittedBy(){return submittedBy;}public Instant getSubmittedAt(){return submittedAt;}
}
